import networkx as nx
G = nx.Graph()
for i in range(20):
    for j in range(i+1, 20):
        if (i // 4) == (j // 4):
            G.add_edge(i, j)
if nx.is_connected(G) and nx.girth(G) >= 7 and G.number_of_edges() >= 37:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
